/**
 * Shared column builders, Postgres enums and custom types for every domain schema file.
 *
 * Conventions (see docs/architecture/knowledge-schema.md):
 *  - snake_case columns (drizzle `casing: "snake_case"`), so TS keys are camelCase.
 *  - uuid primary keys generated by PostgreSQL 18's built-in `uuidv7()` (time-ordered, so
 *    b-tree inserts stay append-mostly and ids sort by creation time).
 *  - timestamptz everywhere.
 *  - Actor columns (`created_by`, `published_by`, ...) are FKs to Better Auth's `users.id`
 *    (text; db/schema/auth.ts is owned by the auth work stream). Never CASCADE: provenance
 *    must survive. Participants are not users and never appear in actor columns.
 *  - `is_demo` marks fixture/demo rows. Demo rows can never reach a non-demo study: composite
 *    foreign keys `(x_id, is_demo) -> x(id, is_demo)` keep demo and real graphs disjoint and
 *    triggers (migration 0003) guard snapshots and studies.
 */
import { sql } from "drizzle-orm";
import { boolean, customType, pgEnum, text, timestamp, uuid } from "drizzle-orm/pg-core";

import * as v from "../../src/lib/validation/enums";
import { users } from "./auth";

// ---------------------------------------------------------------------------------------
// Column builders
// ---------------------------------------------------------------------------------------

/** uuid primary key, `uuidv7()` default (PostgreSQL 18 built-in). */
export const pk = () => uuid().primaryKey().default(sql`uuidv7()`);

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const tsz = () => timestamp({ withTimezone: true });

/**
 * Optional acting staff user (Better Auth `users.id`, text). ON DELETE SET NULL: but on
 * append-only tables the resulting UPDATE is rejected, so a user with research history
 * cannot be hard-deleted; lock the account instead (`users.disabled_at`).
 */
export const actorId = () => text().references(() => users.id, { onDelete: "set null" });

/** Required acting staff user. ON DELETE RESTRICT. */
export const requiredActorId = () =>
  text()
    .notNull()
    .references(() => users.id, { onDelete: "restrict" });

export const isDemo = () => boolean().notNull().default(false);

/** Postgres full-text vector. Drizzle has no built-in tsvector column type. */
export const tsvector = customType<{ data: string; driverData: string }>({
  dataType() {
    return "tsvector";
  },
});

// ---------------------------------------------------------------------------------------
// SQL fragments reused by check constraints
// ---------------------------------------------------------------------------------------

export const SHA256_HEX_RE = "^[0-9a-f]{64}$";
export const SLUG_RE = "^[a-z0-9]+(-[a-z0-9]+)*$";

